import{_ as l,o as t,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- OSD: Peering / Latency","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- OSD: Peering / Latency","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-06T00:00:00.000Z","tags":["[Ceph]","[分布式存储]","[性能优化]","[数据对等连接]","[尾部延迟]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Peering_Latency.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Peering_Latency.md","lastUpdated":1780459816000}'),r={name:"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Peering_Latency.md"};function a(p,i,o,s,_,g){return t(),e("div",null,[...i[0]||(i[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议主题</strong>： Ceph分布式存储性能优化：提升数据对等连接速度和降低尾部延迟</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Sam Guang、Sage、以及其他未具名的研发人员</p><p><strong>会议内容</strong>：</p><p><strong>主要议题</strong>：</p><ol><li><p><strong>更快的数据对等连接</strong>：</p><ul><li>讨论了Ceph在对等连接过程中存在的多个往返延迟问题，包括构建OSD列表、请求pg notify信息、确定权威OSD、获取信息调整日志、发送info消息激活等步骤。</li><li>提出了优化方案，如基于历史间隔预先确定权威OSD、仅请求活动集的缺失日志和日志、启动对等连接时跳过某些步骤等。</li></ul></li><li><p><strong>降低尾部延迟</strong>：</p><ul><li>探讨了OSD长时间非活动状态导致的尾部延迟问题，包括系统启动时的预填充pg temp、设置primary affinity为0、OSD崩溃时立即标记为down、客户端驱动读取等方案。</li></ul></li></ol><p><strong>决定事项</strong>：</p><ul><li>将“更快的数据对等连接”和“降低尾部延迟”两个蓝图合并为一个。</li><li>探索使用客户端驱动读取来解决尾部延迟问题。</li><li>考虑在启动对等连接时跳过某些步骤，以减少往返延迟。</li><li>考虑将primary affinity设置为0，以避免不必要的IO等待。</li><li>探索使用系统启动时预填充pg temp来减少启动时间。</li><li>探索在OSD崩溃时立即将其标记为down的方法。</li></ul><p><strong>后续行动计划</strong>：</p><ul><li>Sam Guang将更新蓝图，以包含上述讨论的优化方案。</li><li>Sage将研究客户端驱动读取的实现方案。</li><li>其他研发人员将探索使用客户端驱动读取来解决尾部延迟问题。</li><li>团队将评估将primary affinity设置为0的可行性。</li><li>团队将评估使用系统启动时预填充pg temp的可行性。</li><li>团队将评估在OSD崩溃时立即将其标记为down的可行性。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>数据对等连接</li><li>尾部延迟</li><li>pg temp</li><li>primary affinity</li><li>客户端驱动读取</li><li>CephFS</li><li>RBD</li><li>librados</li><li>libcephfs</li><li>RadosGW</li><li>RESTful API</li><li>认证</li><li>授权</li><li>加密</li><li>纠错码</li><li>复制</li><li>快照</li><li>克隆</li><li>虚拟化</li><li>云计算</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>混合云</li><li>跨云</li><li>存储集群</li><li>节点</li><li>硬盘</li><li>SSD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>网络</li><li>网络拓扑</li><li>故障域</li><li>恢复</li><li>弹性</li><li>负载均衡</li><li>缓存</li><li>压缩</li><li>去重</li><li>分层</li><li>性能调优</li><li>基准测试</li><li>验证</li></ul>",13)])])}const f=l(r,[["render",a]]);export{D as __pageData,f as default};
